<script setup lang="ts">import type{RakingResult}from '../types/domain';import{number,percent}from '../utils/format';defineProps<{result:RakingResult}>();</script><template><div class="calibration-summary"><div class="summary-main"><small>原始样本 / 有效样本</small><h2>{{result.sample_count}} <span>→</span> {{number(result.effective_sample_size,1)}}</h2><p>Kish设计效应 {{number(result.design_effect,3)}} · {{result.converged?'边际已收敛':'未收敛，不能批准交付'}}</p></div><div><small>最大归一残差</small><b>{{percent(result.max_residual)}}</b><p>{{result.iterations}} 次迭代</p></div><div><small>平均出行时长 / 分钟</small><b>{{number(result.unweighted_mean)}} → {{number(result.weighted_mean)}}</b><p>原始均值 → 加权均值</p></div></div></template>
